{
 "kind": "decision",
 "step": "vet",
 "questions": {
  "signal_credible": {
   "type": "noul",
   "instructions": "Is there a credible periodic transit signal at the candidate period (or its alias)? Weigh tls_sde_broad (>9 very strong, >6 strong, <6 weak/possible false positive), tls_snr or aliases.reported.depth_snr (>7 reliable), at least 2 transits with data (distinct_transit_count / transits_with_data), a duration that is hours rather than a large fraction of the period, a depth that is plausible (planets ~0.01-3%), windows_agreeing_with_period (most windows finding P, P/2 or 2P means the signal survives preprocessing), and period_matches_rotation_harmonic (a candidate at the rotation period or a harmonic is residual activity unless the depth/shape is clearly transit-like). An odd/even mismatch alone does not make it non-credible: that is an alias question below.\n",
   "criteria": {
    "true": "SDE >= 6 and SNR >= 7 with >= 2 transits, and not explained by rotation residuals or a single artifact.",
    "false": "SDE < 6, SNR < 7, fewer than 2 transits with data, the period equals a rotation harmonic with no transit-like dip, or windows disagree so the period depends on preprocessing."
   }
  },
  "period_choice": {
   "type": "choice",
   "instructions": "Which period is the planet's true orbital period? Use the aliases block: aliases.reported.depth_at_phase_0p5 is the dip halfway between reported transits; aliases.double.depth_at_phase_0p5 is the depth of the in-between transits if the period were 2P; odd/even depths compare alternating transits. Default to reported when evidence is absent (for example the in-between epochs fall in data gaps; empty_transit_count > 0 alone is not evidence for 2P). If signal_credible is false, answer reported.\n",
   "criteria": {
    "reported": "Alternate transits have equal depths (odd_even_mismatch_sigma < 3), the 2P alias's phase-0.5 dip equals the reported depth (the in-between transits are real), and there is no equal dip halfway between reported transits.",
    "double": "Alternate transits differ (reported odd_even_mismatch_sigma >= 3, e.g. an eclipsing binary's primary/secondary), or the in-between epochs have data and show no dip (aliases.double.depth_at_phase_0p5_snr < 3 while aliases.double.depth_snr is high).",
    "half": "An equally deep dip sits halfway between reported transits (aliases.reported.depth_at_phase_0p5 comparable to depth_ppt with snr >= 7) and the half alias's odd/even depths agree."
   }
  }
 },
 "thresholds": {
  "signal_credible": 0.2,
  "period_choice": 0.7
 }
}
